package com.ryanjei.orushio.pve.map;import java.io.IOException;import java.nio.file.*;import java.nio.file.attribute.BasicFileAttributes;import java.util.EnumSet;
final class SafeFiles{private SafeFiles(){}static void copyTree(Path source,Path target)throws IOException{Files.walkFileTree(source,EnumSet.noneOf(FileVisitOption.class),Integer.MAX_VALUE,new SimpleFileVisitor<>(){public FileVisitResult preVisitDirectory(Path dir,BasicFileAttributes attrs)throws IOException{if(Files.isSymbolicLink(dir))throw new IOException("シンボリックリンクは利用できません。");Files.createDirectories(target.resolve(source.relativize(dir)));return FileVisitResult.CONTINUE;}public FileVisitResult visitFile(Path file,BasicFileAttributes attrs)throws IOException{if(Files.isSymbolicLink(file))throw new IOException("シンボリックリンクは利用できません。");Files.copy(file,target.resolve(source.relativize(file)),StandardCopyOption.COPY_ATTRIBUTES);return FileVisitResult.CONTINUE;}});}static void deleteTree(Path target)throws IOException{Files.walkFileTree(target,new SimpleFileVisitor<>(){public FileVisitResult visitFile(Path file,BasicFileAttributes attrs)throws IOException{Files.delete(file);return FileVisitResult.CONTINUE;}public FileVisitResult postVisitDirectory(Path dir,IOException e)throws IOException{if(e!=null)throw e;Files.delete(dir);return FileVisitResult.CONTINUE;}});}}
